using System;
using System.Linq;
using System.Collections.Generic;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Input;

namespace CET6Word {
 public static partial class UITests {
  static void Arrow(Key key){var e=new KeyEventArgs(Keyboard.PrimaryDevice,PresentationSource.FromVisual(ui.Window),Environment.TickCount,key){RoutedEvent=Keyboard.PreviewKeyDownEvent};ui.Window.RaiseEvent(e);Pump();}
  static void V2UITests(Action<string,Action> test){Open();
   test("V2 WPF: page jump, invalid input, per-page sizes and rapid arrows",()=>{Nav("StudyNav");var input=Controls<TextBox>().Single();input.Text="0";Click("跳转");Check(StudyList().Items.Count==20,"invalid jump changed page");input.Text="3";Click("跳转");var first=((WordView)StudyList().Items[0]).Word.Id;Check(first==new LearningEngine(state).StudyWords()[40].Id,"page 3 content");((Button)ui.Window.FindName("StudyNav")).Focus();for(int i=0;i<5;i++)Arrow(Key.Right);Check(((WordView)StudyList().Items[0]).Word.Id==new LearningEngine(state).StudyWords()[140].Id,"rapid flips lost input");Controls<TextBox>().Single().Focus();Arrow(Key.Left);Check(((WordView)StudyList().Items[0]).Word.Id==new LearningEngine(state).StudyWords()[140].Id,"text focus flipped page");Controls<ComboBox>().Single(c=>c.Tag as string=="page-size").SelectedItem=10;Pump();Check(StudyList().Items.Count==10,"size change");Capture("v2-pagination.png");});
   test("V2 WPF: live search, read-only details, every sentence audio, preserved study page",()=>{var before=((WordView)StudyList().Items[0]).Word.Id;var learned=state.Progress.Values.Sum(p=>p.LearnCount);Click("搜索");var input=Controls<TextBox>().Single(t=>t.Tag as string=="search-input");input.Text="abandon";Pump();var results=Controls<ListBox>().Single(l=>l.DisplayMemberPath=="English");Check(results.Items.Count>0,"live search empty");results.SelectedIndex=0;Pump();var row=Controls<Button>().Where(b=>b.Tag as string=="expand").Select(b=>b.DataContext as WordView).First(r=>r!=null&&r.Context=="search");Check(row.Level==2&&row.ExampleChinese.Length>0,"search bilingual detail");Check(!Controls<Button>().Any(b=>b.IsVisible&&b.DataContext==row&&(b.Tag as string=="master"||b.Tag as string=="favorite")),"search management exposed");int calls=audio.Calls.Count;Click(Controls<Button>().First(b=>b.DataContext==row&&b.Tag as string=="speak"));Click(Controls<Button>().First(b=>b.DataContext==row&&b.Tag as string=="example"));Check(audio.Calls.Count==calls+2,"manual detail audio");Click(Controls<Button>().First(b=>b.DataContext==row&&b.Tag as string=="more-examples"));Settle();var extra=Controls<Button>().First(b=>b.IsVisible&&b.Tag as string=="example-extra");var expected=((Example)extra.DataContext).English;Click(extra);Check(audio.Calls.Last()==expected,"extra example played wrong text");input.Text="放弃";Pump();Check(results.Items.Count==0,"Chinese query matched");input.Text="abandon";Pump();results.SelectedIndex=0;Pump();Capture("v2-search.png");Check(state.Progress.Values.Sum(p=>p.LearnCount)==learned,"search learned a word");Click("关闭");Settle();Check(((WordView)StudyList().Items[0]).Word.Id==before,"search changed page");});
   test("V2 WPF: three book entries, original independent pagination and passive viewing",()=>{Nav("BooksNav");Check(new[]{"原词书","收藏词本","已记诵词本"}.All(t=>Controls<Button>().Any(b=>b.Content as string==t)),"three entries missing");Click("原词书");Check(Controls<ListBox>().Single().Items.Count==20,"original shared study size");var row=(WordView)Controls<ListBox>().Single().Items[0];int learned=state.Progress.Values.Sum(p=>p.LearnCount);Click(RowButton("expand"));Click(RowButton("expand"));Check(state.Progress.Values.Sum(p=>p.LearnCount)==learned,"original browsing learned");Click("下一页");Check(((WordView)Controls<ListBox>().Single().Items[0]).Word.Id==state.Vocabularies[0].Words[20].Id,"original source order");Nav("StudyNav");Check(StudyList().Items.Count==10,"original size affected study");Nav("BooksNav");Click("原词书");Check(((WordView)Controls<ListBox>().Single().Items[0]).Word.Id==state.Vocabularies[0].Words[20].Id,"original page not retained");Capture("v2-original.png");});
   test("V2 WPF: favorite page sizes shared, notebook pages retained independently",()=>{var e=new LearningEngine(state);var a=e.AddNotebook("分页 A");var b=e.AddNotebook("分页 B");foreach(var w in e.Current.Words.Take(70)){e.PutInNotebook(a,w.Id);e.PutInNotebook(b,w.Id);}Nav("BooksNav");Click("收藏词本");Controls<ComboBox>().First().SelectedItem=a;Pump();Click("下一页");Controls<ComboBox>().First().SelectedItem=b;Pump();Check(((WordView)Controls<ListBox>().Single().Items[0]).Word.Id==e.Current.Words[0].Id,"book B inherited book A page");Controls<ComboBox>().Single(c=>c.Tag as string=="page-size").SelectedItem=30;Pump();Controls<ComboBox>().First().SelectedItem=a;Pump();Check(Controls<ListBox>().Single().Items.Count==30&&state.Reading.Positions["book:"+a.Id].Page==2,"shared size or own page lost");Controls<ListBox>().Single().SelectedIndex=0;Controls<ComboBox>().ElementAt(1).SelectedItem=b;Click("加入所选词");Check(b.Words.Distinct().Count()==b.Words.Count,"duplicate membership");Click("移出当前词本");StateStore.Validate(state);});
   test("V2 WPF: recited dynamic filters and original mastery synchronize",()=>{var e=new LearningEngine(state);var target=e.Current.Words[4];e.EndSession();e.StartWith(new List<string>{target.Id},false,"test");e.Submit(target.English);e.Next();Nav("BooksNav");Click("已记诵词本");Check(Controls<ListBox>().Single().Items.Cast<WordView>().Any(r=>r.Word.Id==target.Id),"latest correct missing");Controls<ComboBox>().First().SelectedIndex=1;Pump();Check(Controls<ListBox>().Single().Items.Cast<WordView>().All(r=>e.Evidence(r.Word.Id).LastCorrect==true),"correct filter stale");Controls<ComboBox>().First().SelectedIndex=2;Pump();Check(Controls<ListBox>().Single().Items.Cast<WordView>().All(r=>e.Evidence(r.Word.Id).Mastered),"master filter stale");Capture("v2-recited.png");Nav("BooksNav");Click("原词书");Controls<TextBox>().Single().Text="1";Click("跳转");var row=Controls<ListBox>().Single().Items.Cast<WordView>().Single(r=>r.Word.Id==target.Id);var master=Controls<Button>().Single(x=>x.DataContext==row&&x.Tag as string=="master");Click(master);Check(e.Evidence(target.Id).Mastered,"original master did not sync");Click(Controls<Button>().Single(x=>x.DataContext is WordView&&((WordView)x.DataContext).Word.Id==target.Id&&x.Tag as string=="master"));Check(!e.Evidence(target.Id).Mastered&&e.Evidence(target.Id).LastCorrect==true,"restoring master removed correct evidence");});
   test("V2 WPF: original favorite actions retain expanded details and sync status",()=>{Nav("BooksNav");Click("原词书");Controls<TextBox>().Single().Text="1";Click("跳转");var row=(WordView)Controls<ListBox>().Single().Items[0];if(row.Level!=2)Click(RowButton("expand"));int learned=state.Progress.Values.Sum(p=>p.LearnCount);bool before=new LearningEngine(state).Favorite(row.Word.Id);Click(RowButton("favorite"));var next=(WordView)Controls<ListBox>().Single().Items[0];Check(next.Level==2,"favorite collapsed word details");Check(new LearningEngine(state).Favorite(row.Word.Id)!=before,"favorite did not sync");Check(next.StatusLabel.Contains("收藏")==!before,"status stale");Check(state.Progress.Values.Sum(p=>p.LearnCount)==learned,"book favorite counted learning");Click(RowButton("favorite"));});
   test("V2 WPF: all eight nonblocking motion triggers run on the real WPF tree",()=>{Nav("StudyNav");Controls<TextBox>().Single().Text="1";Click("跳转");var row=(WordView)StudyList().Items[0];Click(RowButton("expand"));Check(Controls<FrameworkElement>().Any(x=>x.DataContext==row&&x.Name=="MeaningPanel"&&x.HasAnimatedProperties),"meaning animation missing");Click(RowButton("expand"));Check(Controls<FrameworkElement>().Any(x=>x.DataContext==row&&x.Name=="ExamplePanel"&&x.HasAnimatedProperties),"example animation missing");Click(Controls<Button>().First(x=>x.DataContext==row&&x.Tag as string=="more-examples"));Check(row.More,"more example toggle failed");Settle();Click(Controls<Button>().First(x=>x.DataContext==row&&x.Tag as string=="more-examples"));Settle();Check(!row.More,"more example collapse failed");var favorite=RowButton("favorite");Click(favorite);Check(((System.Windows.Media.ScaleTransform)favorite.RenderTransform).HasAnimatedProperties,"favorite pulse missing");Click(RowButton("master"));Check(Controls<System.Windows.Controls.Image>().Any(x=>x.HasAnimatedProperties),"master removal fade missing");Click("下一页");Check(Controls<ContentControl>().Any(x=>x.RenderTransform is System.Windows.Media.TranslateTransform&&((System.Windows.Media.TranslateTransform)x.RenderTransform).HasAnimatedProperties),"page slide missing");Check(Controls<StackPanel>().Any(x=>x.HasAnimatedProperties),"navigation fade missing");Click("搜索");var input=Controls<TextBox>().Single(x=>x.Tag as string=="search-input");input.Text="adapt";Pump();Check(Controls<ListBox>().Single(x=>x.DisplayMemberPath=="English").Items.Count>0,"search waited for animation");Check(Controls<Border>().Any(x=>x.RenderTransform is System.Windows.Media.TranslateTransform&&((System.Windows.Media.TranslateTransform)x.RenderTransform).HasAnimatedProperties),"search slide missing");Click("关闭");Settle();new LearningEngine(state).EndSession();Nav("QuizNav");Controls<TextBox>().Single().Text="1";Click("开始");Controls<TextBox>().Single().Text="wrong-animation";Click("提交");Check(Controls<TextBlock>().Any(x=>x.Text.Contains("回答错误")&&x.Foreground is System.Windows.Media.SolidColorBrush&&((System.Windows.Media.SolidColorBrush)x.Foreground).HasAnimatedProperties),"feedback color motion missing");Click("查看结果");Click("结束");});
   test("V2 WPF: 10/20/30/50 study sizes compute pages, scrolling never flips",()=>{Nav("StudyNav");foreach(int count in new[]{10,20,30,50,10}){Controls<ComboBox>().Single(c=>c.Tag as string=="page-size").SelectedItem=count;Pump();Check(StudyList().Items.Count==count,"study size "+count);int p=state.Reading.Positions[LearningEngine.StudyKey(state.CurrentVocabulary,"fixed")].Page;StudyScroll().ScrollToBottom();Pump();Check(state.Reading.Positions[LearningEngine.StudyKey(state.CurrentVocabulary,"fixed")].Page==p,"scroll flipped page");}StudyScroll().ScrollToTop();Pump();});
   test("V2 WPF: direct startup page/order/size/scroll restoration, no automatic audio",()=>{Nav("StudyNav");Controls<TextBox>().Single().Text="6";Click("跳转");StudyScroll().ScrollToVerticalOffset(2);Pump();var ids=StudyList().Items.Cast<WordView>().Select(v=>v.Word.Id).ToArray();var anchor=state.Positions[state.CurrentVocabulary].FixedAnchor;int calls=audio.Calls.Count;ui.Window.Close();Open();Check(StudyList().Items.Count==10&&StudyList().Items.Cast<WordView>().Select(v=>v.Word.Id).SequenceEqual(ids),"restart page/size changed");Check(state.Positions[state.CurrentVocabulary].FixedAnchor==anchor,"restart anchor changed");Check(audio.Calls.Count==calls,"restart auto-read");ui.Window.Width=760;ui.Window.Height=560;Pump();Capture("v2-small-window.png");ui.Window.Close();});
  }
 }
}
